# Determine line coordinates and hypotheses candidates compactly
for mode in ['both','2only','0only']:
 G=[[5]*12 for _ in range(28)]
 if mode in ('both','0only'):
  for r in range(20,28): G[r][r-20]=0
 else: G[26][6]=0;G[27][7]=0
 if mode in ('both','2only'):
  for r in range(22,28): G[r][33-r]=2
 else:
  G[25][8]=2;G[26][7]=2;G[27][6]=2
 print(mode,[(r,c,v) for r,row in enumerate(G) for c,v in enumerate(row) if v!=5])
